use std::fs

struct Bst { key: Vec<int>, left: Vec<int>, right: Vec<int>, root: int }

impl Bst {
    fn insert(self, x: int) -> bool {
        if self.root == -1 {
            self.key.push(x)
            self.left.push(-1)
            self.right.push(-1)
            self.root = 0
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.key[cur]
            if x == k { return false }
            let next = if x < k { self.left[cur] } else { self.right[cur] }
            if next == -1 {
                let id: int = self.key.len() as int
                self.key.push(x)
                self.left.push(-1)
                self.right.push(-1)
                if x < k { self.left[cur] = id } else { self.right[cur] = id }
                return true
            }
            cur = next
        }
        false
    }

    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur != -1 {
            let k = self.key[cur]
            if x == k { return true }
            cur = if x < k { self.left[cur] } else { self.right[cur] }
        }
        false
    }

    fn delete(self, x: int) -> bool {
        let mut cur = self.root
        let mut parent = -1
        while cur != -1 && self.key[cur] != x {
            parent = cur
            cur = if x < self.key[cur] { self.left[cur] } else { self.right[cur] }
        }
        if cur == -1 { return false }
        if self.left[cur] != -1 && self.right[cur] != -1 {
            let mut sp = cur
            let mut s = self.right[cur]
            while self.left[s] != -1 {
                sp = s
                s = self.left[s]
            }
            self.key[cur] = self.key[s]
            let rs = self.right[s]
            if sp == cur { self.right[cur] = rs } else { self.left[sp] = rs }
        } else {
            let child = if self.left[cur] != -1 { self.left[cur] } else { self.right[cur] }
            if parent == -1 {
                self.root = child
            } else if self.left[parent] == cur {
                self.left[parent] = child
            } else {
                self.right[parent] = child
            }
        }
        true
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur = self.root
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.left[cur]
            }
            let n = stack.pop().unwrap_or(0)
            out.push("${self.key[n]}")
            cur = self.right[n]
        }
        if out.len() == 0 { "<empty>" } else { out.join(" ") }
    }

    fn height(self) -> int {
        if self.root == -1 { return 0 }
        let mut level: Vec<int> = [self.root]
        let mut h = 0
        while level.len() > 0 {
            h += 1
            let mut nxt: Vec<int> = []
            for n in level {
                if self.left[n] != -1 { nxt.push(self.left[n]) }
                if self.right[n] != -1 { nxt.push(self.right[n]) }
            }
            level = nxt
        }
        h
    }

    fn min(self) -> string {
        if self.root == -1 { return "empty" }
        let mut cur = self.root
        while self.left[cur] != -1 { cur = self.left[cur] }
        "${self.key[cur]}"
    }

    fn max(self) -> string {
        if self.root == -1 { return "empty" }
        let mut cur = self.root
        while self.right[cur] != -1 { cur = self.right[cur] }
        "${self.key[cur]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Bst { key: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").map(|s| s.to_string()).collect()
        let cmd = parts[0]
        let mut arg = 0
        if parts.len() > 1 { arg = parts[1].parse::<int>().unwrap_or(0) }
        if cmd == "insert" {
            if t.insert(arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.delete(arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height()}")
        } else if cmd == "min" {
            println(t.min())
        } else if cmd == "max" {
            println(t.max())
        }
    }
}

